// ---------- Confetti burst (pure CSS/JS, no external libs) ----------
function Confetti({ legendary = false }) {
  const pieces = useMemo(() => {
    const count = legendary ? 60 : 32;
    const colors = ["#D4AF37", "#F2CB6B", "#2FA093", "#E8DCC0", "#A33E3E"];
    return Array.from({ length: count }, (_, i) => ({
      id: i,
      left: Math.random() * 100,
      delay: Math.random() * 0.5,
      duration: 1.5 + Math.random() * 1.3,
      rotate: Math.random() * 360,
      spin: 180 + Math.random() * 540,
      color: colors[Math.floor(Math.random() * colors.length)],
      w: 5 + Math.random() * 6,
      h: 8 + Math.random() * 8,
    }));
  }, [legendary]);
  return (
    <div style={styles.confettiWrap}>
      {pieces.map((p) => (
        <span
          key={p.id}
          style={{
            position: "absolute",
            top: "-14px",
            left: `${p.left}%`,
            width: p.w,
            height: p.h,
            background: p.color,
            opacity: 0.92,
            borderRadius: 1,
            transform: `rotate(${p.rotate}deg)`,
            animation: `confettiFall ${p.duration}s cubic-bezier(0.25,0.46,0.45,0.94) ${p.delay}s forwards`,
            "--spin": `${p.spin}deg`,
          }}
        />
      ))}
    </div>
  );
}

export default function App() {
  const [screen, setScreen] = useState("setup"); // setup | hand-deal | wave-intro | auction | reveal | tie-select | wave-summary-step | wave-summary | final
  const [players, setPlayers] = useState([]);
  const [nameInput, setNameInput] = useState("");
  const [netWorth, setNetWorth] = useState({});
  const [wave, setWave] = useState(1);
  const [totalWaves, setTotalWaves] = useState(3);
  const [assetIndexInWave, setAssetIndexInWave] = useState(0);
  const [assetDeck, setAssetDeck] = useState([]);
  const [currentAsset, setCurrentAsset] = useState(null);
  const [dealtHands, setDealtHands] = useState([]); // array of {name, cards:[..]} for the current wave
  const [dealRevealIndex, setDealRevealIndex] = useState(0); // which player's hand is on screen during pass-and-play
  const [handDealPhase, setHandDealPhase] = useState("pass"); // "pass" = blind handoff screen, "reveal" = cards showing
  const [waveAssets, setWaveAssets] = useState([]); // this wave's 5 assets, shown in the preview + top strip
  const [seatPositions, setSeatPositions] = useState({}); // name -> {x,y} percent-of-screen, tapped once per match
  const [seatArrangeIndex, setSeatArrangeIndex] = useState(0);
  const [tempSeatPick, setTempSeatPick] = useState(null);
  const [bidders, setBidders] = useState({}); // name -> true if bidding
  const [timeLeft, setTimeLeft] = useState(15);
  const [timerActive, setTimerActive] = useState(false);
  const [lastResult, setLastResult] = useState(null);
  const [history, setHistory] = useState([]);
  const [celebrate, setCelebrate] = useState(null); // { legendary, id } drives confetti burst
  const [biddingPool, setBiddingPool] = useState(null); // null = everyone; array = tie-break round restricted to these names
  const [tieSelected, setTieSelected] = useState([]); // names toggled on the tie-select screen
  const timerRef = useRef(null);
  const waveAssetsRef = useRef([]);

  function addPlayer() {
    const n = nameInput.trim();
    if (!n || players.includes(n) || players.length >= 7) return;
    sfx.uiClick();
    setPlayers([...players, n]);
    setNetWorth({ ...netWorth, [n]: 0 });
    setNameInput("");
  }
  function removePlayer(n) {
    sfx.uiClick();
    setPlayers(players.filter((p) => p !== n));
  }

  function drawAssetPool(count, fromPile) {
    // refill/reshuffle whenever we don't have enough left
    let pile = fromPile;
    if (pile.length < count) pile = shuffle(ASSET_POOL);
    const drawn = pile.slice(0, count);
    setAssetDeck(pile.slice(count));
    return drawn;
  }

  const handSizeFor = (n) => (n === 2 ? 7 : 5);

  // Deal this wave's hands (equal totals, shaped to minimize card overlap between
  // players) and draw this wave's 5 assets — both happen up front so the preview
  // and the pass-and-play deal can show everything before bidding starts.
  function setUpWave(pile) {
    const handSize = handSizeFor(players.length);
    let hands = dealHands(players.length, handSize);
    if (!hands) hands = dealEqualTotalsOnce(players.length, handSize); // rare fallback
    if (!hands) {
      // last-resort fallback: plain random hands, never block the game
      const deck = shuffle(buildBidDeck());
      hands = players.map((_, i) => deck.slice(i * handSize, (i + 1) * handSize).sort((a, b) => a - b));
    }
    setDealtHands(players.map((name, i) => ({ name, cards: hands[i] })));
    setDealRevealIndex(0);
    setHandDealPhase("pass");

    const drawn = drawAssetPool(5, pile);
    waveAssetsRef.current = drawn;
    setWaveAssets(drawn);
  }

  function startGame() {
    sfx.uiClick();
    setSeatPositions({});
    setSeatArrangeIndex(0);
    setTempSeatPick(null);
    setScreen("seat-arrange");
  }

  function pickSeat(xPct, yPct) {
    const clamp = (v) => Math.min(92, Math.max(8, v));
    setTempSeatPick({ x: clamp(xPct), y: clamp(yPct) });
  }

  function confirmSeat() {
    if (!tempSeatPick) return;
    sfx.uiClick();
    const name = players[seatArrangeIndex];
    setSeatPositions((sp) => ({ ...sp, [name]: tempSeatPick }));
    setTempSeatPick(null);
    if (seatArrangeIndex + 1 < players.length) {
      setSeatArrangeIndex((i) => i + 1);
    } else {
      beginGameAfterSeating();
    }
  }

  function skipSeating() {
    sfx.uiClick();
    setSeatPositions({});
    beginGameAfterSeating();
  }

  function beginGameAfterSeating() {
    sfx.gameStart();
    const tw = waveCountFor(players.length);
    setTotalWaves(tw);
    setWave(1);
    const pile = shuffle(ASSET_POOL);
    setAssetDeck(pile);
    setUpWave(pile);
    setScreen("hand-deal");
  }

  function beginWaveAuction() {
    sfx.uiClick();
    const drawn = waveAssetsRef.current;
    setAssetIndexInWave(0);
    setCurrentAsset(drawn[0]);
    setBidders({});
    setBiddingPool(null);
    setTimeLeft(15);
    setTimerActive(true);
    setScreen("auction");
  }

  function toggleBid(name) {
    if (!timerActive) return;
    setBidders((b) => {
      const next = { ...b };
      if (next[name]) {
        delete next[name];
        sfx.bidOff();
      } else {
        next[name] = true;
        sfx.bidOn();
      }
      return next;
    });
  }

  function stopTimerAndReveal() {
    setTimerActive(false);
    if (timerRef.current) clearInterval(timerRef.current);
    sfx.reveal();
    setScreen("reveal");
  }

  // countdown effect
  React.useEffect(() => {
    if (!timerActive) return;
    if (timeLeft <= 0) {
      stopTimerAndReveal();
      return;
    }
    timerRef.current = setTimeout(() => setTimeLeft((t) => t - 1), 1000);
    return () => clearTimeout(timerRef.current);
  }, [timerActive, timeLeft]);

  // tick sound each second the countdown ticks down (skip the initial reset value)
  React.useEffect(() => {
    if (!timerActive) return;
    if (timeLeft > 0 && timeLeft < 15) {
      (timeLeft <= 3 ? sfx.tickUrgent : sfx.tick)();
    }
  }, [timeLeft, timerActive]);

  // end the bidding window early once every eligible player has placed a bid
  React.useEffect(() => {
    if (!timerActive) return;
    const pool = biddingPool || players;
    if (pool.length > 0 && Object.keys(bidders).length >= pool.length) {
      stopTimerAndReveal();
    }
  }, [bidders, timerActive, biddingPool, players.length]);

  function declareWinner(name) {
    const legendary = currentAsset.value >= 10;
    setNetWorth((nw) => ({ ...nw, [name]: (nw[name] || 0) + currentAsset.value }));
    setLastResult({ winner: name, asset: currentAsset, unclaimed: false });
    setHistory((h) => [...h, { wave, asset: currentAsset, winner: name, value: currentAsset.value }]);
    (legendary ? sfx.legendaryWin : sfx.win)();
    setCelebrate({ legendary, id: Date.now() });
    setBiddingPool(null);
    setScreen("wave-summary-step");
  }

  function declareUnclaimed() {
    sfx.unclaimed();
    setLastResult({ winner: null, asset: currentAsset, unclaimed: true });
    setBiddingPool(null);
    setScreen("wave-summary-step");
  }

  function startTieSelect() {
    sfx.uiClick();
    setTieSelected([]);
    setScreen("tie-select");
  }

  function toggleTieCandidate(name) {
    sfx.uiClick();
    setTieSelected((sel) => (sel.includes(name) ? sel.filter((n) => n !== name) : [...sel, name]));
  }

  function cancelTieSelect() {
    sfx.uiClick();
    setScreen("reveal");
  }

  function confirmTieBreak() {
    if (tieSelected.length < 2) return;
    sfx.tieBreak();
    setBiddingPool(tieSelected);
    setBidders({});
    setTimeLeft(15);
    setTimerActive(true);
    setScreen("auction");
  }

  function nextAssetOrWaveEnd() {
    const nextIdx = assetIndexInWave + 1;
    const waveAssets = waveAssetsRef.current;
    if (nextIdx < waveAssets.length) {
      sfx.uiClick();
      setAssetIndexInWave(nextIdx);
      setCurrentAsset(waveAssets[nextIdx]);
      setBidders({});
      setTimeLeft(15);
      setTimerActive(true);
      setScreen("auction");
    } else {
      if (wave >= totalWaves) {
        sfx.gameOver();
        setCelebrate({ legendary: true, id: Date.now() });
        setScreen("final");
      } else {
        sfx.waveTransition();
        setScreen("wave-summary");
      }
    }
  }

  function nextWave() {
    sfx.uiClick();
    setWave((w) => w + 1);
    setUpWave(assetDeck);
    setScreen("hand-deal");
  }

  function revealHand() {
    sfx.uiClick();
    setHandDealPhase("reveal");
  }

  function advanceHandDeal() {
    sfx.uiClick();
    if (dealRevealIndex + 1 < dealtHands.length) {
      setDealRevealIndex((i) => i + 1);
      setHandDealPhase("pass");
    } else {
      setScreen("wave-intro");
    }
  }

  function resetGame() {
    sfx.uiClick();
    setPlayers([]);
    setNetWorth({});
    setWave(1);
    setAssetDeck([]);
    setHistory([]);
    setCelebrate(null);
    setDealtHands([]);
    setWaveAssets([]);
    setSeatPositions({});
    setSeatArrangeIndex(0);
    setTempSeatPick(null);
    setScreen("setup");
  }

  const ranked = useMemo(
    () => [...players].sort((a, b) => (netWorth[b] || 0) - (netWorth[a] || 0)),
    [players, netWorth]
  );

  return (
    <div style={styles.appRoot}>
      <style>{`${FONT_IMPORT}
        * { box-sizing: border-box; }
        ::selection { background: #D4AF37; color: #0A0E17; }
        input:focus, button:focus-visible { outline: 2px solid #D4AF37; outline-offset: 2px; }
        @keyframes confettiFall {
          0% { transform: translateY(0) rotate(0deg); opacity: 0.95; }
          100% { transform: translateY(70vh) rotate(var(--spin)); opacity: 0; }
        }
        @keyframes urgentPulseCentered {
          0%, 100% { transform: translate(-50%, -50%) scale(1); }
          50% { transform: translate(-50%, -50%) scale(1.1); }
        }
        @keyframes popIn {
          0% { transform: scale(0.85); opacity: 0; }
          100% { transform: scale(1); opacity: 1; }
        }
      `}</style>

      <div style={styles.vignette} />

      <div style={styles.stage}>
        <Header wave={wave} totalWaves={totalWaves} screen={screen} />

        {celebrate && <Confetti key={celebrate.id} legendary={celebrate.legendary} />}

        {screen === "setup" && (
          <SetupScreen
            players={players}
            nameInput={nameInput}
            setNameInput={setNameInput}
            addPlayer={addPlayer}
            removePlayer={removePlayer}
            startGame={startGame}
          />
        )}

        {screen === "seat-arrange" && (
          <SeatArrangeScreen
            playerName={players[seatArrangeIndex]}
            index={seatArrangeIndex}
            total={players.length}
            tempPick={tempSeatPick}
            onPick={pickSeat}
            onConfirm={confirmSeat}
            onSkip={skipSeating}
          />
        )}

        {screen === "hand-deal" && dealtHands.length > 0 && (
          <HandDealScreen
            wave={wave}
            totalWaves={totalWaves}
            hand={dealtHands[dealRevealIndex]}
            index={dealRevealIndex}
            total={dealtHands.length}
            phase={handDealPhase}
            onReveal={revealHand}
            onNext={advanceHandDeal}
          />
        )}

        {screen === "wave-intro" && (
          <WaveIntro
            wave={wave}
            totalWaves={totalWaves}
            players={players}
            assets={waveAssets}
            onStart={beginWaveAuction}
          />
        )}

        {screen === "auction" && currentAsset && (
          <AuctionScreen
            asset={currentAsset}
            index={assetIndexInWave}
            waveAssets={waveAssets}
            players={biddingPool || players}
            seatPositions={seatPositions}
            tieRound={!!biddingPool}
            bidders={bidders}
            toggleBid={toggleBid}
            timeLeft={timeLeft}
            onTimeUp={stopTimerAndReveal}
          />
        )}

        {screen === "reveal" && currentAsset && (
          <RevealScreen
            asset={currentAsset}
            bidders={bidders}
            onDeclareWinner={declareWinner}
            onUnclaimed={declareUnclaimed}
            onTie={startTieSelect}
          />
        )}

        {screen === "tie-select" && (
          <TieSelectScreen
            bidders={Object.keys(bidders)}
            selected={tieSelected}
            onToggle={toggleTieCandidate}
            onConfirm={confirmTieBreak}
            onCancel={cancelTieSelect}
          />
        )}

        {screen === "wave-summary-step" && lastResult && (
          <ResultScreen result={lastResult} netWorth={netWorth} players={players} onNext={nextAssetOrWaveEnd} />
        )}

        {screen === "wave-summary" && (
          <WaveSummary
            wave={wave}
            totalWaves={totalWaves}
            netWorth={netWorth}
            players={players}
            ranked={ranked}
            onNextWave={nextWave}
          />
        )}

        {screen === "final" && (
          <FinalScreen ranked={ranked} netWorth={netWorth} onReset={resetGame} />
        )}
      </div>
    </div>
  );
}

// ---------- Subcomponents ----------

function Header({ wave, totalWaves, screen }) {
  if (screen === "setup" || screen === "seat-arrange") return null;
  const dots = Array.from({ length: totalWaves }, (_, i) => i + 1);
  return (
    <div style={styles.header}>
      <div style={styles.headerTitle}>
        <AnkhIcon size={20} />
        <span style={styles.headerTitleText}>KANZ</span>
      </div>
      <div style={styles.waveDots}>
        {dots.map((d) => (
          <div key={d} style={{ opacity: d <= wave ? 1 : 0.28, transform: d === wave ? "scale(1.15)" : "scale(1)" }}>
            <AnkhIcon size={14} filled={d <= wave} />
          </div>
        ))}
      </div>
    </div>
  );
}

function SetupScreen({ players, nameInput, setNameInput, addPlayer, removePlayer, startGame }) {
  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>PASS-AND-PLAY · 2–7 PLAYERS</div>
      <h1 style={styles.h1}>KANZ</h1>
      <p style={styles.subtitle}>An auction of ancient treasures. Bid boldly. Spend wisely.</p>

      <div style={styles.divider} />

      <div style={styles.fieldRow}>
        <input
          style={styles.input}
          placeholder="Enter player name"
          value={nameInput}
          onChange={(e) => setNameInput(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && addPlayer()}
          maxLength={16}
        />
        <button style={styles.iconBtn} onClick={addPlayer} disabled={players.length >= 7}>
          <Plus size={18} color="#0A0E17" />
        </button>
      </div>

      <div style={styles.playerList}>
        {players.map((p, i) => (
          <div key={p} style={styles.playerChip}>
            <span style={styles.playerChipIndex}>{i + 1}</span>
            <span style={styles.playerChipName}>{p}</span>
            <button style={styles.chipRemove} onClick={() => removePlayer(p)}>
              <X size={14} color="#8A93A8" />
            </button>
          </div>
        ))}
        {players.length === 0 && <div style={styles.emptyHint}>Add at least 2 players to begin.</div>}
      </div>

      <button
        style={{ ...styles.primaryBtn, opacity: players.length >= 2 ? 1 : 0.4 }}
        disabled={players.length < 2}
        onClick={startGame}
      >
        <Play size={18} />
        Start Game
      </button>
      <div style={styles.hintSmall}>{players.length}/7 players · {players.length >= 2 ? `${waveCountFor(players.length)} waves this match` : "need 2+"}</div>
    </div>
  );
}

function SeatArrangeScreen({ playerName, index, total, tempPick, onPick, onConfirm, onSkip }) {
  function handleTap(e) {
    const x = (e.clientX / window.innerWidth) * 100;
    const y = (e.clientY / window.innerHeight) * 100;
    onPick(x, y);
  }
  return (
    <>
      <div onClick={handleTap} style={{ position: "fixed", inset: 0, zIndex: 30, cursor: "crosshair" }} />
      <div style={{ ...styles.panel, position: "relative", zIndex: 31 }}>
        <div style={{ pointerEvents: "none" }}>
          <div style={styles.eyebrow}>SEATING · PLAYER {index + 1} OF {total}</div>
          <h1 style={styles.h1}>{playerName}, Tap Your Seat</h1>
          <p style={styles.subtitle}>
            Hand the device around the table. {playerName} reaches out and taps the spot on the screen closest to
            where they're sitting — that's where their bidding circle will stay for the whole match.
          </p>
        </div>
        <div style={{ pointerEvents: "auto", display: "flex", flexDirection: "column", gap: 10, width: "100%" }}>
          <button
            style={{ ...styles.primaryBtn, opacity: tempPick ? 1 : 0.4 }}
            disabled={!tempPick}
            onClick={onConfirm}
          >
            <ChevronRight size={18} />
            {tempPick ? `Confirm ${playerName}'s Spot` : "Tap Anywhere on Screen First"}
          </button>
          <button style={styles.secondaryBtn} onClick={onSkip}>
            Skip — Use Default Layout Instead
          </button>
        </div>
      </div>
      {tempPick && (
        <div
          style={{
            position: "fixed",
            left: `${tempPick.x}%`,
            top: `${tempPick.y}%`,
            transform: "translate(-50%, -50%)",
            width: "clamp(80px, 24vw, 106px)",
            height: "clamp(80px, 24vw, 106px)",
            borderRadius: "50%",
            border: "2px solid #D4AF37",
            background: "rgba(212,175,55,0.18)",
            boxShadow: "0 0 24px rgba(212,175,55,0.5)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontFamily: "'Cinzel', serif",
            fontWeight: 700,
            color: "#F2CB6B",
            fontSize: 14,
            zIndex: 32,
            pointerEvents: "none",
            padding: 6,
            textAlign: "center",
          }}
        >
          {playerName}
        </div>
      )}
    </>
  );
}

function HandDealScreen({ wave, totalWaves, hand, index, total, phase, onReveal, onNext }) {
  if (!hand) return null;
  const isLast = index + 1 >= total;

  if (phase === "pass") {
    return (
      <div style={styles.panel}>
        <div style={styles.eyebrow}>WAVE {wave} OF {totalWaves} · DEALING</div>
        <h1 style={styles.h1}>Pass to {hand.name}</h1>
        <p style={styles.subtitle}>
          Player {index + 1} of {total}. Make sure only {hand.name} is looking at the screen, then tap below to
          reveal their hand.
        </p>
        <button style={styles.primaryBtn} onClick={onReveal}>
          <Sparkles size={18} />
          I'm {hand.name} — Show Me My Cards
        </button>
      </div>
    );
  }

  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>WAVE {wave} OF {totalWaves} · DEALING</div>
      <h1 style={styles.h1}>{hand.name}'s Hand</h1>
      <p style={styles.subtitle}>
        Everyone this wave gets a hand worth the same total — different cards, equal value. Take these{" "}
        {hand.cards.length} cards, then hide them from the table before passing the device on.
      </p>

      <div style={styles.instructionBox}>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 10, justifyContent: "center", padding: "8px 0" }}>
          {hand.cards.map((v, i) => (
            <div
              key={i}
              style={{
                width: 46,
                height: 62,
                borderRadius: 8,
                border: "1px solid #D4AF37",
                background: "linear-gradient(160deg, #1B2438, #0F1626)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontFamily: "'Cinzel', serif",
                fontWeight: 700,
                fontSize: 20,
                color: "#F2CB6B",
                boxShadow: "0 0 14px rgba(212,175,55,0.25)",
              }}
            >
              {v}
            </div>
          ))}
        </div>
        <div style={{ textAlign: "center", marginTop: 6, color: "#8A93A8", fontSize: 12 }}>
          Hand total: {hand.cards.reduce((s, v) => s + v, 0)}
        </div>
      </div>

      <button style={styles.primaryBtn} onClick={onNext}>
        <ChevronRight size={18} />
        {isLast ? "Hidden — All Hands Dealt, Continue" : "Hidden — Pass to Next Player"}
      </button>
    </div>
  );
}

function WaveIntro({ wave, totalWaves, players, assets, onStart }) {
  const total = assets.reduce((s, a) => s + a.value, 0);
  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>WAVE {wave} OF {totalWaves} · PREVIEW</div>
      <h1 style={styles.h1}>This Round's Treasures</h1>
      <p style={styles.subtitle}>
        All {assets.length} items up for auction this round, worth {total} total. Study them and plan which ones
        are worth your best cards before bidding begins.
      </p>

      <div style={{ display: "flex", flexDirection: "column", gap: 8, margin: "10px 0 18px" }}>
        {assets
          .slice()
          .sort((a, b) => b.value - a.value)
          .map((a) => {
            const tier = TIER_STYLE[a.tier];
            return (
              <div
                key={a.key}
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  padding: "10px 14px",
                  borderRadius: 10,
                  border: `1px solid ${tier.color}55`,
                  background: "rgba(19,27,46,0.6)",
                }}
              >
                <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 2 }}>
                  <span style={{ fontSize: 13, fontWeight: 600, color: "#E8DCC0" }}>{a.name}</span>
                  <span style={{ fontSize: 10, color: tier.color, letterSpacing: 0.4 }}>{tier.label.toUpperCase()}</span>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
                  <AnkhIcon size={16} color="#F2CB6B" />
                  <span style={{ fontFamily: "'Cinzel', serif", fontWeight: 700, color: "#F2CB6B", fontSize: 16 }}>
                    {a.value}
                  </span>
                </div>
              </div>
            );
          })}
      </div>

      <button style={styles.primaryBtn} onClick={onStart}>
        <Sparkles size={18} />
        Start the Auction
      </button>
    </div>
  );
}

function AuctionScreen({ asset, index, waveAssets, players, seatPositions, tieRound, bidders, toggleBid, timeLeft }) {
  const tier = TIER_STYLE[asset.tier];
  const pct = timeLeft / 15;
  const urgent = timeLeft <= 3;

  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>{tieRound ? "TIE-BREAKER ROUND" : `ASSET ${index + 1} OF 5`}</div>

      {!tieRound && waveAssets && waveAssets.length > 0 && (
        <div style={{ display: "flex", gap: 6, marginBottom: 4, flexWrap: "wrap", justifyContent: "center" }}>
          {waveAssets.map((a, i) => {
            const claimed = i < index;
            const isCurrent = i === index;
            return (
              <div
                key={a.key}
                title={a.name}
                style={{
                  width: 30,
                  height: 30,
                  borderRadius: 6,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: 12,
                  fontWeight: 700,
                  fontFamily: "'Cinzel', serif",
                  border: isCurrent ? "1px solid #D4AF37" : "1px solid #2A3348",
                  color: claimed ? "#4A5266" : isCurrent ? "#F2CB6B" : "#8A93A8",
                  background: claimed ? "rgba(19,27,46,0.3)" : isCurrent ? "rgba(212,175,55,0.15)" : "rgba(19,27,46,0.6)",
                  textDecoration: claimed ? "line-through" : "none",
                  opacity: claimed ? 0.5 : 1,
                }}
              >
                {a.value}
              </div>
            );
          })}
        </div>
      )}

      <div
        style={{
          ...styles.timerRing,
          borderColor: urgent ? "#A33E3E" : "#D4AF37",
          animation: urgent ? "urgentPulseCentered 0.5s ease-in-out infinite" : "none",
        }}
      >
        <span style={{ ...styles.timerNum, color: urgent ? "#E86A6A" : "#F2CB6B" }}>{timeLeft}</span>
      </div>

      <div style={{ ...styles.assetCard, boxShadow: `0 0 60px ${tier.glow}`, borderColor: tier.color }}>
        <div style={{ ...styles.tierTag, background: tier.color }}>{tier.label.toUpperCase()}</div>
        {ASSET_IMAGES[asset.key] && (() => {
          const ratio = ASSET_IMAGE_RATIO[asset.key] || 0.75;
          const maxW = 220;
          const maxH = 240;
          // fit the frame to the image's real proportions, capped by the card's box
          const frameW = ratio >= maxW / maxH ? maxW : Math.round(maxH * ratio);
          const frameH = ratio >= maxW / maxH ? Math.round(maxW / ratio) : maxH;
          return (
            <div
              style={{
                ...styles.assetImgWrap,
                width: frameW,
                height: frameH,
                background: `radial-gradient(ellipse at center, ${tier.glow} 0%, #0D1220 70%)`,
              }}
            >
              <img src={ASSET_IMAGES[asset.key]} alt={asset.name} style={styles.assetImg} />
            </div>
          );
        })()}
        <div style={styles.assetName}>{asset.name}</div>
        <div style={styles.assetValueRow}>
          <AnkhIcon size={26} color="#F2CB6B" />
          <span style={styles.assetValue}>{asset.value}</span>
        </div>
      </div>

      <p style={styles.instructionLine}>
        {tieRound
          ? `Tied players only: ${players.join(", ")} — keep your original card face-down and place ONE more card on top of it from your hand. Tap your circle when it's placed. On reveal, add both cards together — highest total wins.`
          : "Place your card face-down on the table now, then tap the circle on your side of the screen to confirm you're bidding — before the timer runs out."}
      </p>

      {players.map((p, i) => {
        const active = !!bidders[p];
        const custom = seatPositions && seatPositions[p];
        const pos = custom || bidCircleLayout(players.length)[i];
        const rotate = custom ? 0 : pos.rotate;
        return (
          <button
            key={p}
            onClick={() => toggleBid(p)}
            style={{
              ...styles.bidCircle,
              left: `${pos.x}%`,
              top: `${pos.y}%`,
              transform: `translate(-50%, -50%) rotate(${rotate}deg)`,
              borderColor: active ? "#D4AF37" : "#2A3348",
              background: active ? "rgba(212,175,55,0.18)" : "rgba(19,27,46,0.92)",
              boxShadow: active ? "0 0 24px rgba(212,175,55,0.5)" : "0 4px 16px rgba(0,0,0,0.35)",
            }}
          >
            <span style={styles.bidCircleName}>{p}</span>
            <span style={{ ...styles.bidCircleStatus, color: active ? "#D4AF37" : "#4A5266" }}>
              {active ? "BIDDING ✓" : "TAP TO BID"}
            </span>
          </button>
        );
      })}

    </div>
  );
}

function RevealScreen({ asset, bidders, onDeclareWinner, onUnclaimed, onTie }) {
  const names = Object.keys(bidders);
  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>REVEAL</div>
      <h1 style={{ ...styles.h1, animation: "popIn 0.3s ease-out" }}>{asset.name}</h1>
      <p style={styles.subtitle}>
        {names.length === 0
          ? "No one bid on this asset."
          : "Everyone reveal your card on the table now. Tap whoever played the highest number."}
      </p>

      {names.length === 0 ? (
        <button style={styles.primaryBtn} onClick={onUnclaimed}>
          <ChevronRight size={18} />
          Continue — Unclaimed
        </button>
      ) : (
        <>
          <div style={styles.playerBidGrid}>
            {names.map((name) => (
              <button key={name} onClick={() => onDeclareWinner(name)} style={styles.winnerPickBtn}>
                <Crown size={18} color="#D4AF37" />
                <span style={styles.bidToggleName}>{name}</span>
              </button>
            ))}
          </div>
          {names.length >= 2 && (
            <button style={styles.tieBtn} onClick={onTie}>
              It's a Tie — Pick Who
            </button>
          )}
          {names.length >= 2 && (
            <p style={styles.hintSmall}>
              Tie? Tied players stack one more card on top of their bid and reveal the combined total. Still tied
              after that — do it again.
            </p>
          )}
        </>
      )}
    </div>
  );
}

function TieSelectScreen({ bidders, selected, onToggle, onConfirm, onCancel }) {
  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>TIE-BREAKER</div>
      <h1 style={styles.h1}>Who Tied?</h1>
      <p style={styles.subtitle}>Tap everyone who played the same highest card. They'll draw and bid again for this asset.</p>

      <div style={styles.playerBidGrid}>
        {bidders.map((name) => {
          const active = selected.includes(name);
          return (
            <button
              key={name}
              onClick={() => onToggle(name)}
              style={{
                ...styles.bidToggle,
                borderColor: active ? "#D4AF37" : "#2A3348",
                background: active ? "rgba(212,175,55,0.12)" : "transparent",
              }}
            >
              <span style={styles.bidToggleName}>{name}</span>
              <span style={{ ...styles.bidToggleStatus, color: active ? "#D4AF37" : "#4A5266" }}>
                {active ? "TIED ✓" : "TAP TO SELECT"}
              </span>
            </button>
          );
        })}
      </div>

      <button
        style={{ ...styles.primaryBtn, opacity: selected.length >= 2 ? 1 : 0.4 }}
        disabled={selected.length < 2}
        onClick={onConfirm}
      >
        <ChevronRight size={18} />
        {selected.length < 2 ? "Select at Least 2" : `Tie-Break Between ${selected.length}`}
      </button>
      <button style={styles.secondaryBtn} onClick={onCancel}>
        Cancel — Back to Reveal
      </button>
    </div>
  );
}

function ResultScreen({ result, netWorth, players, onNext }) {
  const { winner, asset, unclaimed } = result;
  return (
    <div style={styles.panel}>
      {unclaimed ? (
        <>
          <div style={styles.eyebrow}>UNCLAIMED</div>
          <h1 style={styles.h1}>{asset.name}</h1>
          <p style={styles.subtitle}>No one bid. The treasure is lost to the sands.</p>
        </>
      ) : (
        <>
          <div style={styles.eyebrow}>WINNER</div>
          <div style={{ ...styles.winnerBadge, animation: "popIn 0.35s ease-out" }}>
            <Trophy size={40} color="#D4AF37" />
          </div>
          <h1 style={{ ...styles.h1, animation: "popIn 0.35s ease-out" }}>{winner}</h1>
          <p style={styles.subtitle}>
            wins <strong style={{ color: "#F2CB6B" }}>{asset.name}</strong> worth {asset.value}
          </p>
        </>
      )}

      <div style={styles.netWorthList}>
        {players.map((p) => (
          <div key={p} style={styles.netWorthRow}>
            <span>{p}</span>
            <span style={styles.netWorthValue}>
              <AnkhIcon size={13} color="#8A93A8" />
              {netWorth[p] || 0}
            </span>
          </div>
        ))}
      </div>

      <button style={styles.primaryBtn} onClick={onNext}>
        <ChevronRight size={18} />
        Continue
      </button>
    </div>
  );
}

function WaveSummary({ wave, totalWaves, netWorth, players, ranked, onNextWave }) {
  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>WAVE {wave} COMPLETE</div>
      <h1 style={styles.h1}>Standings</h1>

      <div style={styles.standingsList}>
        {ranked.map((p, i) => (
          <div key={p} style={styles.standingsRow}>
            <span style={styles.standingsRank}>{i + 1}</span>
            <span style={styles.standingsName}>{p}</span>
            <span style={styles.standingsValue}>
              <AnkhIcon size={14} color="#D4AF37" />
              {netWorth[p] || 0}
            </span>
          </div>
        ))}
      </div>

      <p style={styles.subtitle}>Discard remaining hand cards. Fresh hands next wave.</p>

      <button style={styles.primaryBtn} onClick={onNextWave}>
        <ChevronRight size={18} />
        Begin Wave {wave + 1} of {totalWaves}
      </button>
    </div>
  );
}

function FinalScreen({ ranked, netWorth, onReset }) {
  return (
    <div style={styles.panel}>
      <div style={styles.eyebrow}>MATCH COMPLETE</div>
      <div style={styles.winnerBadge}>
        <Crown size={48} color="#D4AF37" />
      </div>
      <h1 style={styles.h1}>{ranked[0]} Wins</h1>
      <p style={styles.subtitle}>Richest collector of the age.</p>

      <div style={styles.standingsList}>
        {ranked.map((p, i) => (
          <div key={p} style={{ ...styles.standingsRow, ...(i === 0 ? styles.standingsRowWinner : {}) }}>
            <span style={styles.standingsRank}>{i + 1}</span>
            <span style={styles.standingsName}>{p}</span>
            <span style={styles.standingsValue}>
              <AnkhIcon size={14} color={i === 0 ? "#0A0E17" : "#D4AF37"} />
              {netWorth[p] || 0}
            </span>
          </div>
        ))}
      </div>

      <button style={styles.primaryBtn} onClick={onReset}>
        <Sparkles size={18} />
        New Game
      </button>
    </div>
  );
}

